<?php
namespace App\Http\Controllers;
use App\Models\{TripRate,Warehouse,TripType,VehicleGroup,VehicleType,TripPayment,Client,Route as TripRoute}; use Illuminate\Http\{Request,RedirectResponse,JsonResponse}; use Illuminate\Validation\Rule; use Illuminate\View\View;
class TripRateController extends Controller {
 public function index(Request $request): View|JsonResponse { if($request->expectsJson()||$request->ajax()) return $this->dataTable($request); return view('trip-rates.index',['vehicleGroups'=>VehicleGroup::where('is_active',1)->orderBy('vehicle_group_description')->get(),'clients'=>Client::where('is_active',1)->orderBy('client_code')->get(),'tripTypes'=>TripType::where('is_active',1)->orderBy('trip_type')->get(),'payments'=>TripPayment::where('is_active',1)->orderBy('payment_type')->get(),'vehicleTypes'=>VehicleType::where('is_active',1)->orderBy('vehicle_type')->get()]); }
 private function dataTable(Request $r): JsonResponse { $q=TripRate::query(); $total=(clone $q)->count(); $search=trim((string)$r->input('search.value',$r->input('search',''))); if($search!=='') $q->where(fn($x)=>$x->where('trip_number','like',"%$search%")->orWhere('client_code','like',"%$search%")->orWhere('trip_type','like',"%$search%")->orWhere('payment_type','like',"%$search%")->orWhere('vehicle_type','like',"%$search%")); foreach(['vehicle_group','client_code','payment_type','vehicle_type'] as $f) if($r->input($f)) $q->where($f,$r->input($f)); if($r->input('delivery_type')) $q->where('trip_type',$r->input('delivery_type')); if($r->input('status')==='active') $q->where('is_active',1); if($r->input('status')==='inactive') $q->where('is_active',0); $filtered=(clone $q)->count(); $cols=['trip_number','trip_type','payment_type','client_code','vehicle_group','driver_rate','is_active']; $order=$cols[(int)$r->input('order.0.column',0)]??'trip_number'; $dir=$r->input('order.0.dir')==='desc'?'desc':'asc'; $rows=$q->orderBy($order,$dir)->offset((int)$r->input('start',0))->limit(min(max((int)$r->input('length',15),1),100))->get(); $data=$rows->map(fn($x)=>['trip_number'=>e($x->trip_number),'trip_type'=>e($x->trip_type),'payment_type'=>e($x->payment_type),'client_code'=>e($x->client_code),'route'=>e($x->route_origin).' to '.e($x->farthest_destination),'vehicle'=>e($x->vehicle_group).' / '.e($x->vehicle_type),'driver_rate'=>number_format($x->driver_rate,2),'status'=>'<span class=\"status-badge '.($x->is_active?'status-active':'status-inactive').'">'.($x->is_active?'Active':'Inactive').'</span>','actions'=>'<a class=\"table-action\" href=\"'.route('trip-rates.edit',$x).'\">Edit</a>']); return response()->json(['draw'=>(int)$r->input('draw',0),'recordsTotal'=>$total,'recordsFiltered'=>$filtered,'data'=>$data]); }
 public function create(): View { return view('trip-rates.create',$this->formData(new TripRate())); }
 public function store(Request $r): RedirectResponse { $data=$this->validateRate($r); $data['created_by']=$r->user()->id; $data['updated_by']=$r->user()->id; TripRate::create($data); return redirect()->route('trip-rates.index')->with('success','Trip rate created successfully.'); }
 public function edit(TripRate $tripRate): View { return view('trip-rates.edit',$this->formData($tripRate)); }
 public function update(Request $r,TripRate $tripRate): RedirectResponse { $data=$this->validateRate($r); $data['updated_by']=$r->user()->id; $tripRate->update($data); return redirect()->route('trip-rates.index')->with('success','Trip rate updated successfully.'); }
 public function destroy(TripRate $tripRate): RedirectResponse { $tripRate->delete(); return back()->with('success','Trip rate deleted successfully.'); }
 private function formData(TripRate $r): array { return ['tripRate'=>$r,'warehouses'=>Warehouse::where('is_active',1)->orderBy('warehouse_code')->get(),'tripTypes'=>TripType::where('is_active',1)->orderBy('trip_type')->get(),'vehicleGroups'=>VehicleGroup::where('is_active',1)->orderBy('vehicle_group_description')->get(),'vehicleTypes'=>VehicleType::where('is_active',1)->orderBy('vehicle_type')->get(),'payments'=>TripPayment::where('is_active',1)->orderBy('payment_type')->get(),'clients'=>Client::where('is_active',1)->orderBy('client_code')->get(),'routes'=>TripRoute::where('is_active',1)->orderBy('province')->orderBy('city')->get()]; }
 private function validateRate(Request $r): array { return $r->validate(['warehouse_code'=>['required',Rule::exists('warehouses','warehouse_code')],'trip_type'=>['required',Rule::exists('trip_types','trip_type')],'vehicle_group'=>['required',Rule::exists('vehicle_groups','vehicle_group_description')],'vehicle_type'=>['required',Rule::exists('vehicle_types','vehicle_type')],'trip_number'=>'required|string|max:50','payment_type'=>['required',Rule::exists('trip_payments','payment_type')],'client_code'=>['required',Rule::exists('clients','client_code')],'route_origin'=>'required|string|max:150','farthest_destination'=>'required|string|max:150','cargo_capacity'=>'required|numeric|min:0','minimum_drop'=>'required|numeric|min:0','driver_rate'=>'required|numeric|min:0','helper_rate'=>'required|numeric|min:0','driver_cash_released_percentage'=>'required|numeric|between:0,100','helper_cash_released_percentage'=>'required|numeric|between:0,100','additional_driver_rate'=>'required|numeric|min:0','additional_helper_rate'=>'required|numeric|min:0','bypass_fuel_liters'=>'required|numeric|min:0','is_interisland'=>'boolean','is_with_tollfee'=>'boolean','is_bypass_fuel_usage'=>'boolean','is_active'=>'required|boolean']); }
}
